def minSegmentLength(points, k):
    pts = sorted(points)
    if not pts:
        return 0

    def strips(length):
        count = 0
        end = None
        for x in pts:
            if end is None or x > end:
                count += 1
                end = x + length
        return count

    lo, hi = 0, pts[-1] - pts[0]
    while lo < hi:
        mid = (lo + hi) // 2
        if strips(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
